begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select plan(34);
insert into auth.users(id,email) select ('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'risk-'||n||'@test.local' from generate_series(1,8)n;insert into profiles(id,email,full_name) select id,email,'Risk User '||right(id::text,2) from auth.users where id::text like'b1000000-%';
insert into organizations(id,name,created_by)values('b2000000-0000-4000-8000-000000000001','Risk Org','b1000000-0000-4000-8000-000000000001'),('b2000000-0000-4000-8000-000000000002','Other Risk Org','b1000000-0000-4000-8000-000000000008');insert into organization_members(organization_id,user_id,role,status)values('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','Administrator','Active'),('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000002','Member','Active'),('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000003','Member','Active'),('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000004','Member','Active'),('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000005','Member','Active'),('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000006','Member','Active'),('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000007','Member','Inactive'),('b2000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000008','Administrator','Active');
insert into projects(id,organization_id,name,business_objective,project_manager_id,sponsor_name,lifecycle_phase,status,start_date,target_completion_date,overall_health,scope_health,schedule_health,budget_health,resource_health,risk_health,created_by)values('b3000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','Risk Project','Test','b1000000-0000-4000-8000-000000000002','Sponsor','Initiation','Draft','2026-01-01','2026-12-31','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','b1000000-0000-4000-8000-000000000001'),('b3000000-0000-4000-8000-000000000002','b2000000-0000-4000-8000-000000000002','Other','Test','b1000000-0000-4000-8000-000000000008','Sponsor','Initiation','Draft','2026-01-01','2026-12-31','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','b1000000-0000-4000-8000-000000000008');
insert into project_members(id,project_id,user_id,access_level,left_at)values('b4000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000002','Project Manager',null),('b4000000-0000-4000-8000-000000000002','b3000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000003','Project Member',null),('b4000000-0000-4000-8000-000000000003','b3000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000004','Stakeholder',null),('b4000000-0000-4000-8000-000000000004','b3000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000005','Read Only',null),('b4000000-0000-4000-8000-000000000005','b3000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000006','Project Member',now()),('b4000000-0000-4000-8000-000000000006','b3000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000007','Project Member',null),('b4000000-0000-4000-8000-000000000007','b3000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000008','Project Manager',null),('b4000000-0000-4000-8000-000000000008','b3000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000008','Project Manager',null);
select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);set local role authenticated;
select lives_ok($$select create_project_risk('b3000000-0000-4000-8000-000000000001','Supplier delay','Supplier may miss date','Threat','Supplier',4::smallint,5::smallint,'Reduce','Qualify backup','Lead time','b4000000-0000-4000-8000-000000000002','2026-08-01')$$,'Administrator creates threat');select is((select risk_score from project_risks),20::smallint,'Score generated');select throws_ok($$insert into project_risks(project_id,title,description,risk_type,category,probability,impact,response_strategy,response_plan,owner_membership_id,review_date,created_by)values('b3000000-0000-4000-8000-000000000001','Direct','D','Threat','Scope',1,1,'Accept','P','b4000000-0000-4000-8000-000000000002','2026-08-01','b1000000-0000-4000-8000-000000000001')$$,'42501','permission denied for table project_risks','Direct insert denied');select throws_ok($$update project_risks set title='Direct'$$,'42501','permission denied for table project_risks','Direct update denied');select throws_ok($$delete from project_risks$$,'42501','permission denied for table project_risks','Delete denied');
select throws_ok($$select create_project_risk('b3000000-0000-4000-8000-000000000001','Bad','D','Threat','Scope',1::smallint,1::smallint,'Exploit','P','', 'b4000000-0000-4000-8000-000000000002','2026-08-01')$$,'23514',null,'Threat rejects opportunity strategy');select throws_ok($$select create_project_risk('b3000000-0000-4000-8000-000000000001','Bad','D','Opportunity','Scope',1::smallint,1::smallint,'Avoid','P','', 'b4000000-0000-4000-8000-000000000002','2026-08-01')$$,'23514',null,'Opportunity rejects threat strategy');select lives_ok($$select create_project_risk('b3000000-0000-4000-8000-000000000001','Opportunity','May accelerate','Opportunity','Schedule',3::smallint,3::smallint,'Share','Plan','', 'b4000000-0000-4000-8000-000000000001','2026-08-02')$$,'Opportunity strategy succeeds');
select throws_ok($$select create_project_risk('b3000000-0000-4000-8000-000000000001','Bad owner','D','Threat','Scope',1::smallint,1::smallint,'Accept','P','', 'b4000000-0000-4000-8000-000000000003','2026-08-01')$$,'23514','The selected risk owner is not eligible.','Stakeholder owner rejected');select throws_ok($$select create_project_risk('b3000000-0000-4000-8000-000000000001','Bad owner','D','Threat','Scope',1::smallint,1::smallint,'Accept','P','', 'b4000000-0000-4000-8000-000000000004','2026-08-01')$$,'23514','The selected risk owner is not eligible.','Read only owner rejected');select throws_ok($$select create_project_risk('b3000000-0000-4000-8000-000000000001','Bad owner','D','Threat','Scope',1::smallint,1::smallint,'Accept','P','', 'b4000000-0000-4000-8000-000000000005','2026-08-01')$$,'23514','The selected risk owner is not eligible.','Departed owner rejected');select throws_ok($$select create_project_risk('b3000000-0000-4000-8000-000000000001','Bad owner','D','Threat','Scope',1::smallint,1::smallint,'Accept','P','', 'b4000000-0000-4000-8000-000000000006','2026-08-01')$$,'23514','The selected risk owner is not eligible.','Inactive org owner rejected');select throws_ok($$select create_project_risk('b3000000-0000-4000-8000-000000000001','Bad owner','D','Threat','Scope',1::smallint,1::smallint,'Accept','P','', 'b4000000-0000-4000-8000-000000000007','2026-08-01')$$,'23514','The selected risk owner is not eligible.','Cross project owner rejected');select throws_ok($$select create_project_risk('b3000000-0000-4000-8000-000000000001','Bad owner','D','Threat','Scope',1::smallint,1::smallint,'Accept','P','', 'b4000000-0000-4000-8000-000000000008','2026-08-01')$$,'23514','The selected risk owner is not eligible.','Arbitrary manager label rejected');reset role;
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000002',true);set local role authenticated;select lives_ok($$select update_project_risk((select id from project_risks where title='Supplier delay'),'Supplier delay revised','D','Threat','Supplier',5::smallint,5::smallint,'Transfer','Plan','', 'b4000000-0000-4000-8000-000000000002','2026-08-03')$$,'Assigned manager edits');select is((select risk_score from project_risks where title='Supplier delay revised'),25::smallint,'Reassessment regenerates score');select lives_ok($$select transition_project_risk((select id from project_risks where title='Supplier delay revised'),'Monitoring')$$,'Identified to Monitoring');select lives_ok($$select transition_project_risk((select id from project_risks where title='Supplier delay revised'),'Mitigating')$$,'Monitoring to Mitigating');select lives_ok($$select transition_project_risk((select id from project_risks where title='Supplier delay revised'),'Monitoring')$$,'Mitigating to Monitoring');select throws_ok($$select transition_project_risk((select id from project_risks where title='Supplier delay revised'),'Realized',' ')$$,'22023','Meaningful terminal notes are required.','Realization notes required');select lives_ok($$select transition_project_risk((select id from project_risks where title='Supplier delay revised'),'Realized','Supplier missed date.')$$,'Manager realizes');select ok((select realized_by='b1000000-0000-4000-8000-000000000002' and realized_at is not null from project_risks where title='Supplier delay revised'),'Realization audit trusted');select throws_ok($$select transition_project_risk((select id from project_risks where title='Supplier delay revised'),'Closed','No longer relevant')$$,'42501','Risk transition is not permitted.','Realized cannot close');select throws_ok($$select update_project_risk((select id from project_risks where title='Supplier delay revised'),'Edit','D','Threat','Scope',1::smallint,1::smallint,'Accept','P','', 'b4000000-0000-4000-8000-000000000002','2026-08-01')$$,'42501','Terminal risks cannot be changed.','Terminal edit rejected');select lives_ok($$select transition_project_risk((select id from project_risks where title='Opportunity'),'Closed','Opportunity expired.')$$,'Identified closes');select ok((select closed_by='b1000000-0000-4000-8000-000000000002' and closed_at is not null from project_risks where title='Opportunity'),'Closure audit trusted');reset role;
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000003',true);set local role authenticated;select is((select count(*)from project_risks),2::bigint,'Project Member reads');select throws_ok($$select transition_project_risk((select id from project_risks limit 1),'Monitoring')$$,'42501','Risk transition is not permitted.','Owner remains read only');reset role;select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000004',true);set local role authenticated;select is((select count(*)from project_risks),2::bigint,'Stakeholder reads');reset role;select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000005',true);set local role authenticated;select is((select count(*)from project_risks),2::bigint,'Read Only reads');reset role;select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000006',true);set local role authenticated;select is((select count(*)from project_risks),0::bigint,'Inactive project membership cannot read');reset role;select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000007',true);set local role authenticated;select is((select count(*)from project_risks),0::bigint,'Inactive organization membership cannot read');reset role;select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000008',true);set local role authenticated;select is((select count(*)from project_risks),0::bigint,'Cross organization cannot read');reset role;set local role anon;select throws_ok($$select * from project_risks$$,'42501','permission denied for table project_risks','Anonymous denied');reset role;select * from finish();rollback;
